import {esc} from './utils.js';
// Tokenize raw text once; never reprocess generated markup or execute snippets.
export function highlight(code){const pattern=/(\/\/[^\n]*|#[^\n]*|\/\*[\s\S]*?\*\/|"(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*'|`(?:\\.|[^`\\])*`|\b(?:const|let|var|function|return|async|await|for|of|in|if|else|class|new|true|false|null|undefined|def|print|int|val|fun|func|defer|type|void|public|static|struct|import|from|while|try|catch|throw|final|println)\b|\b\d+(?:\.\d+)?\b|\b[A-Za-z_$][\w$]*(?=\())/g;let out='',at=0;for(const match of code.matchAll(pattern)){out+=esc(code.slice(at,match.index));const token=match[0];const kind=/^(\/\/|#|\/\*)/.test(token)?'comment':/^["'`]/.test(token)?'string':/^\d/.test(token)?'number':/^[A-Za-z_$][\w$]*$/.test(token)&&code[match.index+token.length]==='('?'fn':'key';out+=`<span class="tok-${kind}">${esc(token)}</span>`;at=match.index+token.length}return out+esc(code.slice(at))}
export function codeBlock(code,language,settings){if(!code)return '';return `<div class="code-block"><div class="code-header"><span>${esc(language)}</span><div class="code-actions"><button data-action="expand-code" aria-label="Expand code">Expand</button><button data-action="copy-code">Copy</button></div></div><pre><code>${code.split('\n').map((line,i)=>`<span class="code-line">${settings.lineNumbers?`<span class="line-number" aria-hidden="true">${i+1}</span>`:''}${highlight(line)||' '}</span>`).join('')}</code></pre><template>${esc(code)}</template></div>`}
